import { describe, it, expect } from 'vitest';
import type { ImageMetadata } from 'astro';
import { getImagesOptimized } from './images-optimization';
import type { ImagesOptimizer } from './images-optimization';

/** Stub ImageMetadata for a source image of the given dimensions. */
function fakeImage(width: number, height: number): ImageMetadata {
  return { src: '/fake.png', width, height, format: 'png' };
}

/**
 * An ImagesOptimizer spy that records the breakpoints it receives
 * and returns a minimal srcset-shaped result.
 */
function captureSpy(): { breakpoints: number[]; optimizer: ImagesOptimizer } {
  const record: { breakpoints: number[] } = { breakpoints: [] };
  const optimizer: ImagesOptimizer = async (_image, breakpoints) => {
    record.breakpoints = breakpoints;
    return breakpoints.map((w) => ({ src: `/fake-${w}.webp`, width: w }));
  };
  return { get breakpoints() { return record.breakpoints; }, optimizer };
}

/** The deviceSizes array as defined in images-optimization.ts config. */
const deviceSizes = [640, 750, 828, 960, 1080, 1280, 1668, 1920, 2048, 2560, 3200, 3840, 4480, 5120, 6016];

describe('getImagesOptimized – narrow image baseline (pre-fix)', () => {
  it('uses deviceSizes breakpoints for a 256px-wide image when no widths are supplied', async () => {
    const spy = captureSpy();
    const image = fakeImage(256, 256);

    await getImagesOptimized(image, { layout: 'constrained' }, spy.optimizer);

    // Current (broken) behaviour: breakpoints are derived from deviceSizes,
    // not imageSizes, even though the source is only 256px wide.
    // For constrained layout, getBreakpoints returns [width, 2*width, ...deviceSizes < 2*width]
    // width=256, doubleWidth=512 → deviceSizes.filter(w => w < 512) is empty,
    // so breakpoints = [256, 512].
    // The point is that imageSizes (which has values like 16,32,48,...,384 that
    // would be appropriate for a 256px image) is NOT consulted at all.
    // The widths default was config.deviceSizes, not config.imageSizes.

    // Verify no imageSizes values appear in the breakpoints
    const imageSizes = [16, 32, 48, 64, 96, 128, 256, 384];
    const imageSizesOnly = imageSizes.filter((s) => s < 256); // values smaller than source width
    const hasImageSizesEntries = imageSizesOnly.some((s) => spy.breakpoints.includes(s));

    expect(hasImageSizesEntries).toBe(false);

    // Verify the breakpoints are derived from deviceSizes + the image width
    // (constrained layout: [width, doubleWidth, ...deviceSizes < doubleWidth])
    expect(spy.breakpoints).toContain(256); // the source width
    expect(spy.breakpoints).toContain(512); // 2x the source width

    // No deviceSizes entry is < 512, so only [256, 512] remain
    for (const bp of spy.breakpoints) {
      expect(bp <= 512).toBe(true);
    }
  });
});

